DO $$ DECLARE d text; BEGIN SELECT pg_get_constraintdef(oid) INTO STRICT d FROM pg_constraint WHERE conrelid='cmd_command'::regclass AND conname='cmd_command_command_type_check'; ALTER TABLE cmd_command DROP CONSTRAINT cmd_command_command_type_check; EXECUTE format('ALTER TABLE cmd_command ADD CONSTRAINT cmd_command_command_type_check %s',replace(d,'CHECK (','CHECK (command_type=''resolve_regulatory_task'' OR ')); END $$;
CREATE TABLE cmd_regulatory_task_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),actor_id bigint NOT NULL,operation_rule_id bigint NOT NULL,operation_code text NOT NULL,skill_rule_id bigint NOT NULL,case_reference text NOT NULL CHECK(btrim(case_reference)<>''),authority_reference text NOT NULL CHECK(btrim(authority_reference)<>''),law_level smallint NOT NULL CHECK(law_level>=0),illegal_material_present boolean NOT NULL,illegal_modifier smallint NOT NULL CHECK(illegal_modifier IN(0,-2)),task_command_id bigint NOT NULL UNIQUE REFERENCES cmd_actor_task_receipt(command_id),check_total smallint NOT NULL,effect smallint NOT NULL,succeeded boolean NOT NULL,FOREIGN KEY(actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id),FOREIGN KEY(operation_rule_id,operation_code,skill_rule_id) REFERENCES rule_regulatory_operation_skill(rule_id,operation_code,skill_rule_id),CHECK((operation_code='pass-ship-inspection' AND illegal_modifier=CASE WHEN illegal_material_present THEN -2 ELSE 0 END) OR (operation_code<>'pass-ship-inspection' AND NOT illegal_material_present AND illegal_modifier=0)));
